#!/usr/bin/env python3
import html, json, pathlib, shutil
from index_videos import discover
ROOT=pathlib.Path(__file__).resolve().parents[1]
def esc(v): return html.escape(str(v),quote=True)
def main():
    d=json.loads((ROOT/'data/results.json').read_text()); slots=json.loads((ROOT/'data/video_slots.json').read_text()); videos=discover()
    def media(key):
        title=slots.get(key,{'title':'Additional recordings'})['title']; items=videos[key]
        if not items: return f'<div><div class="media-box placeholder"><span class="play" aria-hidden="true">▷</span><strong>{esc(title)}</strong><small>Video coming soon</small></div><p class="caption">{esc(title)}</p></div>'
        return ''.join(f'<figure><div class="media-box"><video controls preload="metadata" playsinline aria-label="{esc(v["title"])}"><source src="{esc(v["src"])}">Your browser does not support this video. <a href="{esc(v["src"])}">Download video</a>.</video></div><figcaption class="caption">{esc(v["title"])}</figcaption></figure>' for v in items)
    def section(title,content,narrow=False):
        return '<section class="section"><div class="container is-max-desktop">'+('<div class="columns is-centered"><div class="column is-four-fifths">' if narrow else '')+f'<h2 class="title is-3 has-text-centered">{title}</h2>'+content+('</div></div>' if narrow else '')+'</div></section>'
    body=section('Abstract','<div class="content"><p>We investigate language-guided motion planning using a Transformer that predicts planar waypoints from mission preferences and structured scene geometry. The pipeline combines language intent parsing, Transformer waypoint prediction, trajectory optimization, and residual-based safety verification. Offline evaluation measures imitation error against expert routes across held-out scenes. The implementation also supports trajectory-level adaptive conformal updates and synchronized experiment logging. This project page presents the available offline results; hardware demonstrations and empirical adaptive-coverage evaluation will be added as recordings become available.</p></div>',True)
    body+=section('Framework',media('framework')+'<div class="pipeline"><div>Language + scene<small>Intent and obstacle geometry</small></div><div>Transformer<small>Eight XY waypoints</small></div><div>Optimization<small>State and control trajectory</small></div><div>Verification<small>Calibrated residual tubes</small></div></div>',True)
    body+=section('Structured Waypoint Transformer','<div class="content"><p>The model combines a MiniLM text encoder with scene tokens, three fusion layers, and three waypoint decoder layers. It predicts eight XY waypoints at fixed altitude. The dataset contains 4,000 scenes split 80/10/10 by scene, with 21,114 training, 2,688 validation, and 2,598 test examples. These are offline model results, not flight trials.</p></div><div class="columns"><div class="column is-half"><img class="figure" src="assets/images/route_examples.png" alt="Six expert and Transformer route comparisons, including a high-error chair preference"><p class="caption">Expert and predicted routes under six language preferences.</p></div><div class="column is-half"><img class="figure" src="assets/images/component_diagnostics.png" alt="Gradient and input sensitivity diagnostics"><p class="caption">Component gradients and input sensitivity diagnostics.</p></div></div>')
    body+=section('Language-Guided Mission Planning','<div class="content"><p>OpenAI parses mission intent; the Transformer produces waypoints. Recordings will illustrate how preferences and scene geometry affect a complete mission.</p></div>'+media('mission')+media('transformer'),True)
    body+=section('Hardware Demonstrations','<p class="caption">Recording slots — no hardware performance claims are made from the offline results.</p><div class="media-grid">'+''.join(media(k) for k in ('hardware','perception','control','clearance'))+'</div>')
    body+=section('Adaptive Conformal Prediction','<div class="content"><p>The implementation supports residual calibration and trajectory-level adaptive updates, with HRRT expert comparisons in adaptive mode. The recordings below are reserved for future demonstrations. Measured long-term coverage is not available in the saved evaluation.</p></div><div class="media-grid">'+''.join(media(k) for k in ('acp','expert','calibration'))+'</div>')
    metrics='<div class="columns is-mobile">'+''.join(f'<div class="column metric"><strong>{value}</strong><span>{label}</span></div>' for value,label in [('0.2773 m','Validation mean error'),('0.2919 m','Test mean error'),('86.46%','Validation verification rate')])+'</div>'
    metrics+='<div class="evidence-note">Archived checkpoint: epoch 67 of 100. The saved calibration quantile and safety radius are unavailable (recorded as infinity). The verification rate is a saved offline metric; it is not a calibrated coverage guarantee or hardware success rate.</div>'
    metrics+='<div class="table-wrap"><table class="table"><thead><tr><th>Waypoint error</th><th>Validation</th><th>Test</th></tr></thead><tbody>'+''.join(f'<tr><td>{label}</td><td>{d["validation"][key]:.4f} m</td><td>{d["test"][key]:.4f} m</td></tr>' for label,key in [('Mean','mean_euclidean_imitation_loss_m'),('Median','median_waypoint_error_m'),('95th percentile','p95_waypoint_error_m'),('Maximum','maximum_waypoint_error_m')])+'</tbody></table></div>'
    body+=section('Offline Evaluation',metrics+'<img class="figure" src="assets/images/training_curves.png" alt="Training and validation curves over 100 epochs"><p class="caption">Saved training curves. Unavailable radius values must not be interpreted as finite safety bounds.</p>')
    rows=''.join(f'<tr><td>{esc(r["preference"])}</td><td>{r["full_route_mean_error_m"]:.4f} m</td></tr>' for r in d['route_examples'])
    body+=section('Language Preference Comparisons','<img class="figure" src="assets/images/route_examples.png" alt="All six route examples from the saved evaluation"><div class="table-wrap"><table class="table"><thead><tr><th>Preference</th><th>Mean route error</th></tr></thead><tbody>'+rows+'</tbody></table></div><p class="subtle">All six saved examples are shown, including the larger-error chair preference. These examples share one scene and do not establish generalization on their own.</p>')
    if videos['additional']: body+=section('Additional Recordings',media('additional'))
    body+=section('Results and Reproducibility','<div class="content"><p>The figures and metrics are exported from the saved Transformer evaluation. <a href="data/results.json">Download the metrics and route coordinates</a>. Source snapshot: <a href="'+d['provenance']['repository']+'/tree/'+d['provenance']['snapshot_commit']+'">'+d['provenance']['snapshot_commit'][:8]+'</a>. The current software includes subsequent calibration and mission integration changes; these archived measurements do not validate those changes.</p></div>',True)
    template=(ROOT/'templates/index.html').read_text(); rendered=template.replace('<!-- CONTENT -->',body)
    (ROOT/'index.html').write_text(rendered)
    (ROOT/'data/videos.json').write_text(json.dumps(videos,indent=2)+'\n')
    dist=ROOT/'dist'
    if dist.exists(): shutil.rmtree(dist)
    dist.mkdir(); shutil.copy2(ROOT/'index.html',dist/'index.html'); (dist/'.nojekyll').touch()
    for folder in ('assets','data','videos'): shutil.copytree(ROOT/folder,dist/folder,ignore=shutil.ignore_patterns('README.md','.gitkeep','placements.json'))
    print('Built index.html and dist/; indexed',sum(map(len,videos.values())),'videos.')
if __name__=='__main__': main()
